// src/helpers/external-source-changes.ts
var sessionId = null;
var revisions = new Map;
var listeners4 = new Set;
var sourceEditCancelledMessage = "The source was edited outside Studio. Pending edits to this file were cancelled.";
var setExternalSourceSession = (next) => {
  if (sessionId === next)
    return;
  sessionId = next;
  revisions.clear();
};
var captureExternalSourceRevision = (files) => sessionId === null ? null : {
  sessionId,
  files: Object.fromEntries(files.map((file) => [
    file,
    revisions.get(normalizeSourceFileName(file, "")) ?? 0
  ]))
};
var isCurrentExternalSourceVersion = (file, version) => version.sessionId === sessionId && version.revision >= (revisions.get(normalizeSourceFileName(file, "")) ?? 0);
var subscribeToExternalSourceChanges = (listener) => {
  listeners4.add(listener);
  return () => listeners4.delete(listener);
};
var recordExternalSourceChange = (file, version, resetUndoHistory) => {
  if (version.sessionId !== sessionId)
    return;
  const normalized = normalizeSourceFileName(file, "");
  if ((revisions.get(normalized) ?? 0) >= version.revision)
    return;
  revisions.set(normalized, version.revision);
  invalidateSourceFileRemappings(normalized);
  invalidateOptimisticEffectProps(normalized);
  invalidateOptimisticEffectHistory(normalized, resetUndoHistory);
  for (const listener of listeners4)
    listener(normalized);
  for (const entry of Internals7.OptimisticEffects.getSnapshot()) {
    if (normalizeSourceFileName(entry.nodePath.absolutePath, "") === normalized)
      Internals7.OptimisticEffects.invalidateFile(entry.nodePath.absolutePath);
  }
};

